/** MIT.Original continuous U-slot top plate;flex only graph connected cap,all fixed shell retained. */
import {Button} from '../../core/index.js';
import {THREE} from './geometry.js';
import {spec} from './dimensions.js';
import {weightedInputHit} from '../../modeling/weighted-input.js';
export class FlexButton extends Button{
 constructor(shell,stem){const proxy=new THREE.Mesh(new THREE.PlaneGeometry(10.8,9.7),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));proxy.name='K117 main invisible input proxy;actual physical tongue is full closed top plate';super({id:'button',label:'K117 G39 real U-slot key',mesh:proxy,position:spec.button.position,travel:spec.button.travelMm,longPressMs:0,meta:{gpio:39,role:'visual-control',motion:'Original continuous U-slot tongue only',scope:'Physical input intent;no automatic firmware/audio/LED behavior',travelSource:'Own multi-view inferred visual travel,not measurement'}});this.shell=shell;this.stem=stem;this.stemRest=stem.position.z;this.rest=shell.geometry.attributes.position.array.slice();this.norm=shell.geometry.attributes.normal.array.slice();this.weights=new Float32Array(this.rest.length/3);this.slopes=new Float32Array(this.weights.length);this.lastDepth=0;
  const nodes=new Map(),keys=[],p=shell.geometry.attributes.position,eligible=n=>n.y>spec.button.rootY+1e-5;for(let i=0;i<p.count;i++){const key=[p.getX(i),p.getY(i),p.getZ(i)].map(x=>Math.round(x*1e5)).join(',');keys.push(key);if(!nodes.has(key))nodes.set(key,{x:p.getX(i),y:p.getY(i)+shell.position.y,z:p.getZ(i)+shell.position.z,ids:[],near:new Set()});nodes.get(key).ids.push(i);}for(let i=0;i<p.count;i+=3)for(let j=0;j<3;j++)for(let k=0;k<3;k++)if(eligible(nodes.get(keys[i+j]))&&eligible(nodes.get(keys[i+k])))nodes.get(keys[i+j]).near.add(keys[i+k]);
  const candidates=[...nodes].filter(([,n])=>Math.abs(n.x)<5.51&&n.y<4.11&&eligible(n)&&n.z>5),seed=candidates.sort((a,b)=>(a[1].x**2+(a[1].y+.8)**2)-(b[1].x**2+(b[1].y+.8)**2))[0]?.[0];if(!seed)throw new Error('K117 own U tongue seed missing');const seen=new Set(),queue=[seed],span=spec.button.freeY-spec.button.rootY;for(let j=0;j<queue.length;j++){const k=queue[j];if(seen.has(k))continue;seen.add(k);const n=nodes.get(k),t=THREE.MathUtils.clamp((n.y-spec.button.rootY)/span,0,1);for(const i of n.ids){this.weights[i]=t*t*(3-2*t);this.slopes[i]=6*t*(1-t)/span;}queue.push(...n.near);}this.meta.connectedTongueUniqueVertices=seen.size;this.meta.movingVertices=this.weights.filter(w=>w>0).length;const r=new THREE.Ray(new THREE.Vector3(stem.position.x,stem.position.y,0).sub(shell.position),new THREE.Vector3(0,0,1));let anchor=null;for(let i=0;i<p.count;i+=3){const vs=[i,i+1,i+2].map(j=>new THREE.Vector3().fromBufferAttribute(p,j)),point=r.intersectTriangle(...vs,true,new THREE.Vector3());if(!point)continue;const distance=r.origin.distanceTo(point);if(anchor&&distance>=anchor.distance)continue;const bary=THREE.Triangle.getBarycoord(point,...vs,new THREE.Vector3());anchor={distance,point:point.clone().add(shell.position).toArray(),indices:[i,i+1,i+2],barycentric:bary.toArray(),weight:[i,i+1,i+2].reduce((sum,j,k)=>sum+bary.getComponent(k)*this.weights[j],0)};}if(!anchor||anchor.weight<=0)throw new Error('Own K117 integral stem requires moving actual inner-wall anchor');this.stemWeight=anchor.weight;this.stemNativeAnchor=anchor;this.hit(shell,h=>weightedInputHit(this,shell,h));
 }
 update(dt){const changed=super.update(dt),depth=this.getActuationState().depthMm;if(depth===this.lastDepth)return changed;const p=this.shell.geometry.attributes.position,n=this.shell.geometry.attributes.normal;for(let i=0;i<this.weights.length;i++){if(!this.weights[i])continue;const k=i*3;if(depth===0){p.setXYZ(i,this.rest[k],this.rest[k+1],this.rest[k+2]);n.setXYZ(i,this.norm[k],this.norm[k+1],this.norm[k+2]);continue;}const nx=this.norm[k],ny=this.norm[k+1]+depth*this.slopes[i]*this.norm[k+2],nz=this.norm[k+2],l=Math.hypot(nx,ny,nz);p.setXYZ(i,this.rest[k],this.rest[k+1],this.rest[k+2]-depth*this.weights[i]);n.setXYZ(i,nx/l,ny/l,nz/l);}this.stem.position.z=this.stemRest-depth*this.stemWeight;p.needsUpdate=true;n.needsUpdate=true;this.shell.geometry.computeBoundingBox();this.shell.geometry.computeBoundingSphere();this.lastDepth=depth;return true;}
 dispose(){super.dispose();this.shell=null;this.stem=null;this.stemNativeAnchor=null;this.rest=null;this.norm=null;this.weights=null;this.slopes=null;}
}
